export function useWatches(sheet: string, user: string): string[] {
  const asOf = useAsOf();
  const { data } = useQuery({
    queryKey: watchesKey(sheet, user, asOf),
    queryFn: () =>
      getJson<string[]>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/watches/${encodeURIComponent(user)}`, asOf)),
    enabled: sheet !== '' && user !== '',
  });
  return data ?? [];
}
